//! Behavioral equivalence to vectors generated by running the original
//! TypeScript client. The expectations are not generated by this Rust code.
use hermes_gateway::replay::{BarrierState, ReplayAction, ReplayMachine};
use serde_json::{Value, json};

struct Request {
    sid: String,
    generation: u64,
    socket: usize,
    answered: bool,
}
#[derive(Default)]
struct Trace {
    events: Vec<Value>,
    requests: Vec<Value>,
    barriers: Vec<Value>,
    open: Vec<Value>,
    pending: Vec<(String, u64, String)>,
    calls: Vec<Request>,
}
impl Trace {
    fn label(&self) -> String {
        let e = self.events.last().cloned().unwrap_or(Value::Null);
        format!(
            "{}:{}:{}",
            e["session_id"].as_str().unwrap_or(""),
            e["type"].as_str().unwrap_or(""),
            e.get("seq").map(ToString::to_string).unwrap_or_default()
        )
    }
    fn actions(&mut self, actions: Vec<ReplayAction>, socket: usize) {
        let mut resolved = vec![];
        for action in actions {
            match action {
                ReplayAction::Dispatch { event } => self.events.push(event),
                ReplayAction::Request {
                    session_id,
                    params,
                    generation,
                } => {
                    self.requests.push(params);
                    self.calls.push(Request {
                        sid: session_id,
                        generation,
                        socket,
                        answered: false,
                    });
                }
                ReplayAction::Barrier {
                    session_id,
                    generation,
                    valid,
                } => {
                    let mut labels = vec![];
                    self.pending.retain(|(sid, owned, label)| {
                        if sid == &session_id && *owned == generation {
                            labels.push(label.clone());
                            false
                        } else {
                            true
                        }
                    });
                    for label in labels {
                        resolved.push((label, valid));
                    }
                }
            }
        }
        // As JS promise continuations: observers run after synchronous dispatch.
        for (label, valid) in resolved {
            self.barriers.push(json!({"label":label,"valid":valid,"event_count":self.events.len(),"last_event":self.label()}));
        }
    }
}
#[test]
fn original_typescript_replay_vectors_match_rust() {
    let fixture: Value =
        serde_json::from_str(include_str!("fixtures/upstream-replay.json")).unwrap();
    assert_eq!(fixture["vectors"].as_array().unwrap().len(), 18);
    for vector in fixture["vectors"].as_array().unwrap() {
        let mut machine = ReplayMachine::new(vector["replay"] != false);
        let mut trace = Trace::default();
        let mut socket = 0usize;
        for step in vector["steps"].as_array().unwrap() {
            match step["op"].as_str().unwrap() {
                "open" => {
                    let actions = machine.opened();
                    trace.actions(actions, socket);
                    socket += 1;
                }
                "drop" => trace.actions(machine.closed(), socket.saturating_sub(1)),
                "event" => trace.actions(
                    machine.live(step["event"].clone()),
                    socket.saturating_sub(1),
                ),
                "answer" | "error" => {
                    let target = step["socket"]
                        .as_u64()
                        .map(|n| n as usize)
                        .unwrap_or(socket - 1);
                    let request = trace
                        .calls
                        .iter_mut()
                        .find(|r| {
                            !r.answered
                                && r.sid == step["session_id"].as_str().unwrap()
                                && r.socket == target
                        })
                        .expect("fixture request exists");
                    request.answered = true;
                    let sid = request.sid.clone();
                    let generation = request.generation;
                    if target == socket - 1 && step["op"] == "answer" {
                        for request in step["result"]["open_requests"]
                            .as_array()
                            .into_iter()
                            .flatten()
                        {
                            if request["id"].is_string() && request["method"].is_string() {
                                trace.open.push(json!({"id":request["id"],"method":request["method"],"params":request.get("params").filter(|p|p.is_object()).cloned().unwrap_or_else(||json!({})),"replayed":true}));
                            }
                        }
                    }
                    let actions = if step["op"] == "error" {
                        machine.failed(&sid, generation, step["error"]["data"]["reason"].as_str())
                    } else {
                        machine.completed(&sid, generation, step["result"].clone())
                    };
                    trace.actions(actions, socket - 1);
                }
                "barrier" => {
                    let sid = step["session_id"].as_str().unwrap();
                    let label = step["label"].as_str().unwrap();
                    match machine.barrier(sid) {
                        BarrierState::Absent=>trace.barriers.push(json!({"label":label,"absent":true})),
                        BarrierState::Invalid=>trace.barriers.push(json!({"label":label,"valid":false,"event_count":trace.events.len(),"last_event":trace.label()})),
                        BarrierState::Pending(generation)=>trace.pending.push((sid.into(),generation,label.into())),
                    }
                }
                "flood" => {
                    let every = step["touch_every"].as_u64();
                    for index in 0..step["count"].as_u64().unwrap() {
                        trace.actions(machine.live(json!({"type":"message.delta","session_id":format!("s{index}"),"seq":1,"replay_epoch":format!("e{index}")})),socket-1);
                        if every.is_some_and(|every| index % every == 0) {
                            trace.actions(machine.live(json!({"type":"message.delta","session_id":"s0","seq":index+2,"replay_epoch":"e0"})),socket-1);
                        }
                    }
                }
                op => panic!("unknown fixture operation {op}"),
            }
        }
        let actual = json!({"events":trace.events,"watermarks":machine.watermarks(),"session_epochs":machine.session_epochs(),"replay_requests":trace.requests,"barriers":trace.barriers,"open_requests":trace.open});
        assert_eq!(
            actual, vector["expected"],
            "upstream behavioral divergence: {}",
            vector["name"]
        );
    }
}
